const raw      = $execution.customData.get('validationErrors') || '[]';
const errors   = JSON.parse(raw);
const total    = $execution.customData.get('totalProcessed') || '0';
const valid    = $execution.customData.get('totalValid')     || '0';
const errCount = $execution.customData.get('totalErrors')    || '0';

if (errors.length === 0) {
  return [{ json: { skip: true } }];
}

const lines = errors.map(e =>
  `  SKU: ${e.row?.sku || 'N/A'}  →  ${e.error}  (${e.timestamp})`
);

return [{
  json: {
    skip:    false,
    subject: `[N8N WARNING] Stock Sync — ${errCount} validation error(s)`,
    body:    `Stock sync completed with issues.\n\nSummary\n-------\nTotal  : ${total}\nValid  : ${valid}\nErrors : ${errCount}\n\nFailed Rows\n-----------\n${lines.join('\n')}`
  }
}];

const items    = $input.all();
const lowStock = items.filter(i => i.json.low_stock_alert === true);

if (lowStock.length === 0) return [];

const lines = lowStock.map(i =>
  `  • ${i.json.sku}  |  ${i.json.product_name}  |  ${i.json.stock_qty} units left`
);

return [{
  json: {
    subject: `[LOW STOCK] ${lowStock.length} product(s) critically low`,
    body:    `The following products need urgent attention:\n\n${lines.join('\n')}\n\nPlease review and reorder.`
  }
}];

const total  = $execution.customData.get('totalProcessed') || '0';
const valid  = $execution.customData.get('totalValid')     || '0';
const errors = $execution.customData.get('totalErrors')    || '0';

const summary = {
  status: 'complete',
  total:  parseInt(total),
  valid:  parseInt(valid),
  errors: parseInt(errors),
  ts:     new Date().toISOString()
};

console.log('[StockSync Complete]', JSON.stringify(summary));
return [{ json: summary }];

// Build ACK CSV content
const items    = $input.all();
const lines    = ['sku,status,timestamp'];
const ts       = new Date().toISOString();

for (const item of items) {
  lines.push(`${item.json.sku},ACKNOWLEDGED,${ts}`);
}

const csvContent = lines.join('\n');
const filename   = `ack_${Date.now()}.csv`;
const buffer     = Buffer.from(csvContent, 'utf8');

return [{
  json: { filename },
  binary: {
    data: {
      data:     buffer.toString('base64'),
      mimeType: 'text/csv',
      fileName: filename
    }
  }
}];

// ============================================================
// VALIDATE & TRANSFORM
// - Checks required fields
// - Normalises types (int, float)
// - Flags low-stock items (qty <= 10)
// - Stores error list in execution customData
// ============================================================

const items  = $input.all();
const valid  = [];
const errors = [];

for (const item of items) {
  const row = item.json;

  const required = ['sku', 'product_name', 'stock_qty', 'price'];
  const missing  = required.filter(f =>
    row[f] === undefined || row[f] === null || String(row[f]).trim() === ''
  );

  if (missing.length > 0) {
    errors.push({
      row,
      error: `Missing fields: ${missing.join(', ')}`,
      timestamp: new Date().toISOString()
    });
    continue;
  }

  const stockQty = parseInt(row.stock_qty, 10);
  const price    = parseFloat(parseFloat(row.price).toFixed(2));

  if (isNaN(stockQty) || isNaN(price)) {
    errors.push({
      row,
      error: 'stock_qty or price is not a valid number',
      timestamp: new Date().toISOString()
    });
    continue;
  }

  valid.push({
    json: {
      sku:             String(row.sku).trim().toUpperCase(),
      product_name:    String(row.product_name).trim(),
      stock_qty:       stockQty,
      price,
      category:        row.category ? String(row.category).trim() : 'Uncategorised',
      last_updated:    new Date().toISOString(),
      in_stock:        stockQty > 0,
      low_stock_alert: stockQty > 0 && stockQty <= 10
    }
  });
}

$execution.customData.set('validationErrors', JSON.stringify(errors));
$execution.customData.set('totalProcessed',   String(items.length));
$execution.customData.set('totalValid',        String(valid.length));
$execution.customData.set('totalErrors',       String(errors.length));

return valid;
